def cache_sim(capacity, ttl, ops):
    cache = {}  # key -> (value, write_time)
    lru_order = []  # list to track order of keys (for LRU)
    results = []

    for op in ops:
        t = op[1]

        # First, remove any expired entries
        expired_keys = []
        for key, (value, write_time) in cache.items():
            if write_time + ttl <= t:
                expired_keys.append(key)

        for key in expired_keys:
            del cache[key]
            if key in lru_order:
                lru_order.remove(key)

        if op[0] == 'put':
            key = op[2]
            value = op[3]

            # If key already exists, remove it from lru_order
            if key in cache:
                lru_order.remove(key)
            # If key doesn't exist and cache is full, evict LRU
            elif len(cache) >= capacity:
                lru_key = lru_order.pop(0)
                del cache[lru_key]

            # Add the new entry
            cache[key] = (value, t)
            lru_order.append(key)

        elif op[0] == 'get':
            key = op[2]

            if key in cache:
                value, write_time = cache[key]
                # Check if expired
                if write_time + ttl <= t:
                    # Expired, treat as absent
                    results.append(-1)
                    del cache[key]
                    lru_order.remove(key)
                else:
                    # Valid, return value and mark as recently used
                    results.append(value)
                    lru_order.remove(key)
                    lru_order.append(key)
            else:
                results.append(-1)

    return results

